  const parseAtomic=(value,asset)=>{const a=assetById(asset),s=String(value??'').trim();if(!a||!/^\d+(?:\.\d+)?$/.test(s)||s.length>42)return null;const [whole,frac='']=s.split('.');if(frac.length>a.decimals)return null;return BigInt(whole)*units(asset)+BigInt((frac+'0'.repeat(a.decimals)).slice(0,a.decimals));};
  const formatAtomic=(value,asset)=>{const n=BigInt(value),scale=units(asset),fraction=(n%scale).toString().padStart(assetById(asset).decimals,'0').replace(/0+$/,'');return (n/scale).toString()+(fraction?'.'+fraction:'');};
