  const amountField=(label='Amount',value='',min=10,available=null)=>`<div class="amount-field"><label for="amount">${label}</label><div class="amount-input-row"><span class="dollar">$</span><input class="amount-input" name="amount" id="amount" type="number" inputmode="decimal" placeholder="0.00" step="0.01" min="${min}" max="1000000" value="${value}" required><span class="amount-currency">USD</span></div><div class="amount-foot"><span>Minimum ${usd(min*100)}</span>${available!==null?`<span>Available ${usd(available)}</span>`:'<span>USD equivalent</span>'}</div><div class="preset-row">${[25,50,100,250].map(v=>`<button type="button" class="preset" data-action="preset" data-value="${v}">$${v}</button>`).join('')}</div></div>`;
  const paymentBadges=()=>`<div class="payment-badges"><span>${icon('apple')}Pay</span><span>${icon('google')}Pay</span><span class="pay-visa">${visaMark()}</span></div>`;
  function feeQuote(c,amount){const p=planById(c.plan);const initial=c.status==='selected';const activated=(state.activatedPlans||[]).includes(p.id)||state.cards.some(x=>x.id!==c.id&&x.plan===p.id&&['active','frozen'].includes(x.status));const issue=initial&&!activated?p.issue:0;const service=Math.max(p.minimum,Math.round(amount*p.rate));return {pending:false,issue,service,fixed:0,total:amount+issue+service,fee:issue+service};}
  const sourceAtomicFor=(total,w)=>(BigInt(total)*10000n*units(w.asset)+assetById(w.asset).priceMicros-1n)/assetById(w.asset).priceMicros;
  function maxLoad(c,w){if(!w)return 0;let lo=0,hi=Math.min(walletValue(w),100000000);while(lo<hi){const m=Math.ceil((lo+hi)/2);if(sourceAtomicFor(feeQuote(c,m).total,w)<=BigInt(w.balanceAtomic))lo=m;else hi=m-1;}return lo;}
  function setupChecklist(){const picked=state.cards.length>0;const deposited=state.transactions.some(t=>t.type==='deposit'&&t.status==='confirmed');const funded=state.cards.some(c=>c.status==='active'||c.status==='frozen');if(picked&&deposited&&funded)return '';const target=state.cards.find(c=>c.status==='selected')||state.cards[0];return `<section class="setup-checklist"><div class="between"><h2>Finish setting up</h2><small>${[picked,deposited,funded].filter(Boolean).length}/3</small></div>${[[picked,'Choose your card','discover'],[deposited,'Top up your wallet','deposit'],[funded,'Move money to your card',target?'fund/'+target.id:'discover']].map(([done,label,route],i)=>`<a href="#/${route}" class="setup-step ${done?'done':''}"><span class="setup-number">${done?icon('check'):i+1}</span><span>${label}</span>${icon('chevron')}</a>`).join('')}</section>`;}
  // Illustrative spending examples only; these never enter account activity.
