  const HOME_SESSION_KEY=KEY+'-home-session',HOME_ROTATION_KEY=KEY+'-home-alert';
  let homeSession=null,homeVisit=0,homeCleanup=null,quickCardVisible=null;
  const resourceVisits=new Set();
  function eligibleHomeAlerts(){
    const pending=state.cards.find(c=>c.status==='selected');
    const setup=!state.cards.length?{title:'Choose your first card',text:'Find the card that fits you.',route:'discover',label:'Choose card'}:pending?{title:state.balance?'Your card is nearly ready':'Add crypto to get started',text:state.balance?'Top up your card from a wallet.':'Receive crypto into your wallet.',route:state.balance?'fund/'+pending.id:'deposit',label:state.balance?'Top up card':'Receive crypto'}:null;
    return [...(setup?[{id:'setup',image:'resource-coins-v17.png',...setup}]:[]),...(!state.recovery.confirmedAt?[{id:'recovery',image:'insight-abstract-source-v18.png',title:'Secure Your Account',text:'Save your recovery backup.',route:'profile/recovery',label:'Secure account'}]:[]),{id:'ledger',image:'resource-ledger-v17.png',title:'Activate Ledger Sync',text:'Your wallets, together. Coming soon.',action:'resource-ledger',label:'Explore Ledger'},...(state.cards.some(c=>c.status!=='selected')?[{id:'controls',image:'account-plus-v13.png',title:'Your card. Your control.',text:'Freeze or unfreeze in a tap.',action:'resource-controls',label:'Card controls'}]:[]),{id:'exchange',image:'resource-coins-v17.png',title:'Crypto, ready to spend',text:'Convert from your wallet to your card.',action:'resource-exchange',label:'Explore exchange'},{id:'staking',image:'resource-coins-v17.png',title:'Put your crypto to work',text:'Staking · 16% illustrative annual rate.',action:'resource-staking',label:'Preview staking'},{id:'bills',image:'intro-spending-terminal-v10.png',title:'Bills, on autopilot',text:'Automated payments. Coming soon.',action:'resource-bills',label:'Explore the feature'},{id:'support',image:'insight-mint-flow-v18.png',title:'24/7 help and support',text:'Here whenever you need us.',action:'resource-support',label:'Open chat'}];
  }
  function saveHomeSession(){try{sessionStorage.setItem(HOME_SESSION_KEY,JSON.stringify(homeSession));}catch{}}
  function beginHomeSession(force=false){
    if(!force&&homeSession)return homeSession;
    if(!force)try{const saved=JSON.parse(sessionStorage.getItem(HOME_SESSION_KEY));if(saved?.id&&typeof saved.dismissed==='boolean'){homeSession=saved;return saved;}}catch{}
    const eligible=eligibleHomeAlerts();let last;try{last=localStorage.getItem(HOME_ROTATION_KEY);}catch{}
    const index=eligible.findIndex(a=>a.id===last),next=eligible[index<0?0:(index+1)%eligible.length];
    homeSession={id:uid('session'),alertId:next?.id||null,dismissed:false};saveHomeSession();return homeSession;
  }
  function currentHomeAlert(){
    const session=beginHomeSession();if(session.dismissed)return null;
    const eligible=eligibleHomeAlerts(),alert=eligible.find(a=>a.id===session.alertId)||eligible[0];
    if(!alert)return null;
    session.alertId=alert.id;saveHomeSession();try{localStorage.setItem(HOME_ROTATION_KEY,alert.id);}catch{}
    return alert;
  }
  function homeAlert(a){if(!a)return '';return `<aside class="home-alert home-alert-${a.id}" aria-label="Account reminder" data-campaign="${a.id}"><img class="home-alert-image" src="assets/${a.image}" alt="" draggable="false"><div class="grow"><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p>${a.route?`<a href="#/${a.route}">${a.label}${icon('chevron')}</a>`:`<button data-action="${a.action}">${a.label}${icon('chevron')}</button>`}</div><button class="home-alert-close" data-action="dismiss-home-alert" aria-label="Dismiss this reminder until your next sign-in">${icon('close')}</button></aside>`;}
