  function homeCard(c){return `<button class="home-stack-item home-stack-card ${c.status==='frozen'?'is-frozen':''}" data-action="home-card" data-id="${c.id}" style="--stack-ink:${c.design==='black-chrome'?'#f4f4f6':'#151519'}" aria-label="Open ${esc(cardName(c))} card and quick actions"><img src="assets/${designById(c.design).image}" alt="" draggable="false"><span class="stack-balance" aria-hidden="true"><strong>${hideBalance?'••••':usd(c.balance)}</strong></span><span class="stack-drop-arrow" aria-hidden="true">${icon('down')}</span></button>`;}
