  function homeResources(alert){const items=resourceItems(alert);return `<section class="home-resources" aria-labelledby="resources-title"><div class="section-head"><h2 id="resources-title">News and Insights</h2><div class="resource-arrows"><button id="resource-previous" type="button" aria-label="Previous insight" aria-controls="resource-rail">${icon('back')}</button><button id="resource-next" type="button" aria-label="Next insight" aria-controls="resource-rail">${icon('chevron')}</button></div></div><div class="resource-rail" id="resource-rail" role="region" aria-roledescription="carousel" aria-label="News, insights and useful features" tabindex="0">${items.map(t=>`<button class="resource-tile resource-${t.size} resource-${t.kind}" data-action="resource-${t.id}" aria-label="${esc(t.title.replace(/<[^>]+>/g,' ').replace(/\s+/g,' '))}"><img class="resource-image" src="assets/${t.image}" alt="" loading="lazy" draggable="false"><span class="resource-shade" aria-hidden="true"></span><span class="resource-copy"><strong>${t.title}</strong>${t.sub?`<small>${t.sub}</small>`:''}</span><span class="resource-footer">${t.footer}${icon('upRight')}</span></button>`).join('')}</div><p class="resource-status visually-hidden" id="resource-status" aria-live="polite">Insight 1 of ${items.length}. Swipe or drag to explore.</p></section>`;}
  function home(){const alert=currentHomeAlert();return `<div class="dashboard-home home-revamp"><h1 class="visually-hidden">Home</h1><section class="home-total" aria-label="All account balances"><span>Total balance</span><div class="home-total-amount">${hideBalance?'••••••':moneyBig(allAccountBalance())}</div><small>All wallets and cards</small></section><div class="home-quick-actions" aria-label="Quick actions"><button data-action="home-withdraw">${icon('upRight')}<span>Withdraw</span></button><button data-action="home-transfer">${icon('transfer')}<span>Transfer</span></button><a href="#/discover">${icon('card')}<span>New card</span></a><button data-action="add-wallet">${icon('plus')}<span>New wallet</span></button></div>${homeAlert(alert)}<section class="home-stack-section" aria-labelledby="home-wallets-title"><div class="section-head"><h2 id="home-wallets-title">Wallets</h2><button class="stack-add-wallet" data-action="add-wallet" aria-label="Add a new wallet">${icon('plus')}</button></div><div class="home-stack" id="home-wallets">${state.wallets.map(homeWallet).join('')}</div></section><section class="home-stack-section" aria-labelledby="home-cards-title"><div class="section-head"><h2 id="home-cards-title">Cards</h2></div>${state.cards.length?`<div class="home-stack" id="home-cards">${state.cards.map(homeCard).join('')}</div>`:`<a class="home-empty-stack" href="#/discover">${icon('card')}Choose your first card${icon('chevron')}</a>`}</section>${section('Recent activity','activity','View all')}${txList(state.transactions.slice(0,5))}${homeResources(alert)}</div>`;}
