    const receivePanel=`<div class="wallet-receive-panel"><div class="wallet-large-qr"><img src="assets/preview-qr-white-v20.svg" alt="Illustrative QR, not a payment address">${coin(w.asset)}</div><dl class="wallet-receive-facts"><div><dt>Network</dt><dd>${esc(network)}</dd></div><div><dt>Available</dt><dd>${formatAtomic(w.balanceAtomic,w.asset)} ${w.asset}</dd></div></dl><button class="wallet-address-copy" data-action="copy" data-value="${address}" aria-label="Copy demo receiving address">${icon('copy')}<span>${esc('DEMO_'+w.asset+'_'+w.network+'…ADDRESS')}</span></button><p class="quick-demo-note">Demo address and QR · cannot receive funds.</p></div>`;
    const sendPanel=`<form class="wallet-send-form" data-form="withdraw">${errorBox()}<input type="hidden" id="source-wallet" name="walletId" value="${w.id}"><div class="wallet-send-balance"><span>Available</span><strong>${nativeMoney(w.balanceAtomic,w.asset)}</strong></div>${nativeAmountField(w,'Amount to send')}<label class="field"><span class="field-label">Receiving wallet address</span><input class="input" name="address" placeholder="Enter a wallet address" autocomplete="off" minlength="8" maxlength="200" required></label><div class="fee-box" id="fee-box"></div><button class="btn primary full" type="submit">Review send${icon('arrow')}</button><p class="quick-demo-note">Use the matching ${esc(w.asset)} / ${esc(w.network)} network. Demo transfer.</p></form>`;
