  function requestCardReplacement(id){const c=getCard(id);if(!c||c.status==='selected'||c.replacementPending)return;openModal('Replace your card?',`<p>This previews a replacement request for your ${planById(c.plan).name} card. No money moves and no live card is replaced. Issuer requirements and any fees will be connected later.</p>`,`<button class="btn primary full" data-action="confirm-card-replacement" data-id="${c.id}">Request demo replacement${icon('refresh')}</button><button class="demo-link full" data-action="return-quick-card" data-id="${c.id}">Back to card</button>`);}
  function openResource(id){
    if(id==='support')return showChat();if(id==='ledger')return openModal('Ledger Sync · coming soon',`<p>Connect your Ledger wallets in a future update. Your Ledger recovery phrase stays with you; WHOO will never ask you to enter it.</p>`,`<a class="btn secondary full" href="https://www.ledger.com/" target="_blank" rel="noopener noreferrer">Explore Ledger${icon('upRight')}</a>`);
    if(id==='recovery')return go('profile/recovery');if(id==='setup'){const a=eligibleHomeAlerts().find(a=>a.id==='setup');if(a?.route)return go(a.route);return;}
    if(id==='exchange'){const c=state.cards.find(c=>c.status!=='frozen');if(c)return openCardTopup(c.id);return go('discover');}
    if(id==='controls'){const c=state.cards.find(c=>c.status!=='selected');return openModal('Your card. Your control.',`<p>Freeze or unfreeze a card from its quick-access sheet. Spending limits and approval rules are planned for a future update.</p>`,c?`<button class="btn secondary full" data-action="home-card" data-id="${c.id}">Open card controls${icon('lock')}</button>`:`<a class="btn secondary full" href="#/discover">Explore cards${icon('card')}</a>`);}
    if(id==='staking')return openModal('Put your crypto to work.',`<p class="resource-modal-kicker">Staking preview</p><h3 class="resource-modal-rate">Earn up to 16%</h3><p>On crypto and stablecoins, with daily interest planned.</p><p class="form-helper">16% is an illustrative annual rate for this design preview, not a monthly or guaranteed return. Staking is not active. Supported assets, variable rates, payout timing and access terms will be shown before launch.</p>`,`<button class="btn secondary full" data-action="close-modal">Got it</button>`);
    if(id==='bills')return openModal('Bills, on autopilot.',`<p>Automated bill payments are planned for a future update. This tile previews the feature; no bills or payments are created.</p>`,`<button class="btn secondary full" data-action="close-modal">Got it</button>`);
  }
  function mountHome(){
    if(parseRoute().page!=='home')return;
    const stack=$$('.home-stack-item');let press=null,pressTimer,peekTimer,suppressPeekClick=false;
    const clearPeeks=()=>{clearTimeout(peekTimer);stack.forEach(row=>row.classList.remove('balance-peek'));};
    const endPress=()=>{clearTimeout(pressTimer);if(press?.shown){const row=press.row;clearTimeout(peekTimer);peekTimer=setTimeout(()=>row.classList.remove('balance-peek'),1000);}press=null;};
    const onStackDown=e=>{if(e.pointerType!=='touch'&&e.pointerType!=='pen')return;endPress();clearPeeks();suppressPeekClick=false;press={row:e.currentTarget||e.target.closest('.home-stack-item'),x:e.clientX,y:e.clientY,shown:false};pressTimer=setTimeout(()=>{if(!press)return;press.shown=true;suppressPeekClick=true;press.row.classList.add('balance-peek');},330);};
    const onStackMove=e=>{if(press&&(Math.abs(e.clientX-press.x)>8||Math.abs(e.clientY-press.y)>8))endPress();};
    const onStackClick=e=>{if(suppressPeekClick){e.preventDefault();e.stopPropagation?.();suppressPeekClick=false;}};
    stack.forEach(row=>{row.addEventListener('pointerdown',onStackDown);row.addEventListener('pointermove',onStackMove);row.addEventListener('pointerup',endPress);row.addEventListener('pointercancel',endPress);row.addEventListener('click',onStackClick);});
    const rail=$('#resource-rail');let timer,observer,drag=null,touchStart=null,suppressResourceClick=false,releaseTimer,stopped=false,running=false,visible=false,tourIndex=1;
    const tiles=rail?[...rail.querySelectorAll('.resource-tile')]:[],previous=$('#resource-previous'),next=$('#resource-next');
    const maxScroll=()=>Math.max(0,(rail?.scrollWidth||0)-(rail?.clientWidth||0));
    const positions=()=>[...new Set([0,...tiles.map(t=>Math.max(0,Math.min(maxScroll(),t.offsetLeft-(tiles[0]?.offsetLeft||0))))])];
    const scrollResource=(left,smooth=true)=>rail?.scrollTo({left,behavior:smooth&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'smooth':'auto'});
    const stopTour=()=>{stopped=true;running=false;resourceVisits.add(homeVisit);clearTimeout(timer);observer?.disconnect();scrollResource(rail?.scrollLeft||0,false);};
    const startTour=()=>{if(stopped||running||resourceVisits.has(homeVisit)||!visible||document.visibilityState==='hidden')return;const tick=()=>{if(stopped)return;if(!visible||document.visibilityState==='hidden'){running=false;return;}const stops=positions();if(stops.length<2){running=false;timer=setTimeout(startTour,250);return;}if(tourIndex<stops.length){scrollResource(stops[tourIndex++]);timer=setTimeout(tick,1650);}else{scrollResource(0);running=false;resourceVisits.add(homeVisit);observer?.disconnect();timer=null;}};running=true;timer=setTimeout(tick,1800);};
    const onScroll=()=>{if(previous)previous.disabled=rail.scrollLeft<2;if(next)next.disabled=rail.scrollLeft>=maxScroll()-2;const nearest=tiles.reduce((best,t,i)=>Math.abs(t.offsetLeft-(tiles[0]?.offsetLeft||0)-rail.scrollLeft)<Math.abs((tiles[best]?.offsetLeft||0)-(tiles[0]?.offsetLeft||0)-rail.scrollLeft)?i:best,0);const label=$('#resource-status');if(label)label.textContent='Insight '+(nearest+1)+' of '+tiles.length;};
    const moveResource=direction=>{stopTour();const stops=positions(),current=rail.scrollLeft;const target=direction>0?stops.find(x=>x>current+4):[...stops].reverse().find(x=>x<current-4);scrollResource(target??(direction>0?maxScroll():0));};
    const onPrevious=e=>{e.preventDefault();moveResource(-1);},onNext=e=>{e.preventDefault();moveResource(1);};
    const onKey=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();stopTour();if(e.key==='Home')scrollResource(0);else if(e.key==='End')scrollResource(maxScroll());else moveResource(e.key==='ArrowRight'?1:-1);}};
    const onRailDown=e=>{if(e.pointerType!=='mouse'){touchStart={x:e.clientX,y:e.clientY};return;}if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:rail.scrollLeft,active:false};suppressResourceClick=false;};
    const onRailMove=e=>{if(touchStart){const dx=Math.abs(e.clientX-touchStart.x),dy=Math.abs(e.clientY-touchStart.y);if(dx>8&&dx>dy){stopTour();touchStart=null;}else if(dy>8)touchStart=null;}if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x;if(!drag.active){if(Math.abs(dx)<6||Math.abs(dx)<=Math.abs(e.clientY-drag.y))return;stopTour();drag.active=true;suppressResourceClick=true;rail.classList.add('is-dragging');rail.setPointerCapture?.(e.pointerId);}e.preventDefault();rail.scrollLeft=Math.max(0,Math.min(maxScroll(),drag.left-dx));onScroll();};
    const onRailUp=e=>{touchStart=null;if(!drag||drag.id!==e.pointerId)return;const active=drag.active;drag=null;rail.classList.remove('is-dragging');if(rail.hasPointerCapture?.(e.pointerId))rail.releasePointerCapture(e.pointerId);if(active){const stops=positions(),nearest=stops.reduce((a,b)=>Math.abs(a-rail.scrollLeft)<=Math.abs(b-rail.scrollLeft)?a:b,0);scrollResource(nearest);clearTimeout(releaseTimer);releaseTimer=setTimeout(()=>{suppressResourceClick=false;},280);}};
    const onRailClick=e=>{if(suppressResourceClick){e.preventDefault();e.stopPropagation?.();suppressResourceClick=false;}else stopTour();};
    const onWheel=e=>{if(Math.abs(e.deltaX||0)>Math.abs(e.deltaY||0))stopTour();},onFocus=()=>stopTour(),onDrag=e=>e.preventDefault(),onVisibility=()=>{if(document.visibilityState==='hidden'){clearTimeout(timer);running=false;}else startTour();};
    if(rail){rail.addEventListener('scroll',onScroll,{passive:true});rail.addEventListener('pointerdown',onRailDown);rail.addEventListener('pointermove',onRailMove);rail.addEventListener('pointerup',onRailUp);rail.addEventListener('pointercancel',onRailUp);rail.addEventListener('lostpointercapture',onRailUp);rail.addEventListener('click',onRailClick);rail.addEventListener('keydown',onKey);rail.addEventListener('focusin',onFocus);rail.addEventListener('wheel',onWheel,{passive:true});rail.addEventListener('dragstart',onDrag);previous?.addEventListener('click',onPrevious);next?.addEventListener('click',onNext);document.addEventListener('visibilitychange',onVisibility);onScroll();if(!resourceVisits.has(homeVisit)){if(typeof IntersectionObserver!=='undefined'){observer=new IntersectionObserver(entries=>{visible=entries.some(e=>e.isIntersecting);if(visible)startTour();else{clearTimeout(timer);running=false;}},{threshold:.1});observer.observe(rail);}else{visible=true;startTour();}}}
    homeCleanup=()=>{clearTimeout(pressTimer);clearPeeks();clearTimeout(timer);clearTimeout(releaseTimer);observer?.disconnect();stack.forEach(row=>{row.removeEventListener('pointerdown',onStackDown);row.removeEventListener('pointermove',onStackMove);row.removeEventListener('pointerup',endPress);row.removeEventListener('pointercancel',endPress);row.removeEventListener('click',onStackClick);});if(rail){for(const [name,fn]of [['scroll',onScroll],['pointerdown',onRailDown],['pointermove',onRailMove],['pointerup',onRailUp],['pointercancel',onRailUp],['lostpointercapture',onRailUp],['click',onRailClick],['keydown',onKey],['focusin',onFocus],['wheel',onWheel],['dragstart',onDrag]])rail.removeEventListener(name,fn);previous?.removeEventListener('click',onPrevious);next?.removeEventListener('click',onNext);document.removeEventListener('visibilitychange',onVisibility);}};
  }
  function assetWalletRow(w){return `<a class="asset-wallet-row" href="#/wallet/${w.id}">${coin(w.asset)}<span class="grow"><strong>${esc(assetById(w.asset).name)}</strong><small>${esc(w.asset)} · ${esc(w.network)}</small></span><span class="asset-wallet-amount"><strong>${hideBalance?'••••':formatAtomic(w.balanceAtomic,w.asset)}</strong><small>${hideBalance?'••••':'≈ '+usd(walletValue(w))}</small></span>${icon('chevron','asset-wallet-chevron')}</a>`;}
  function wallet(){return `<div class="wallet-screen"><h1 class="visually-hidden">Multi-currency account</h1><section class="wallet-overview" aria-label="Combined crypto balance"><div class="wallet-total-label">Total balance<button class="eye-btn" data-action="hide-balance" aria-label="${hideBalance?'Show':'Hide'} balance">${icon(hideBalance?'eyeOff':'eye')}</button></div><div class="wallet-total-value">${hideBalance?'••••••':moneyBig(state.balance)}</div><p>USD · all crypto wallets</p></section><div class="wallet-primary-actions" aria-label="Wallet actions"><button data-action="wallet-transfer">${icon('transfer')}<span>Transfer</span></button><button data-action="wallet-swap">${icon('refresh')}<span>Swap</span></button><button data-action="wallet-buy">${icon('plus')}<span>Buy</span></button></div><div class="section-head"><h2>Your assets</h2><button class="section-link" data-action="add-wallet">${icon('plus')}Add wallet</button></div><div class="asset-wallet-list">${state.wallets.map(assetWalletRow).join('')}</div>${section('Recent activity','activity','View all')}${txList(state.transactions.filter(t=>t.type!=='card').slice(0,4))}<p class="wallet-account-caption">Your multi-currency account.<br>Hold all your crypto wallets in one place.</p><p class="sample-rate-note">Estimated USD values · sample rates for this preview.</p>${ledgerBanner()}</div>`;}
