    if(a==='home-card'||a==='return-quick-card')return openQuickCard(el.dataset.id);
    if(a==='home-wallet-route'){if(el.dataset.mode==='withdraw')return go('withdraw/'+el.dataset.id);return openQuickWallet(el.dataset.id);}
    if(a==='quick-reveal-card'){quickCardVisible=quickCardVisible===el.dataset.id?null:el.dataset.id;return openQuickCard(el.dataset.id,true);}
    if(a==='quick-lock-card'){const c=getCard(el.dataset.id);if(!c||c.status==='selected')return;c.status=c.status==='frozen'?'active':'frozen';persist();render();return openQuickCard(c.id);}
    if(a==='quick-replace-card')return requestCardReplacement(el.dataset.id);
    if(a==='confirm-card-replacement'){const c=getCard(el.dataset.id);if(!c||c.status==='selected'||c.replacementPending)return;c.replacementPending=true;state.transactions.unshift({id:uid('replace'),type:'replacement',title:'Card replacement requested',subtitle:cardName(c)+' · '+c.last4,amount:0,cardId:c.id,status:'pending',date:now()});persist();render();return openQuickCard(c.id);}
    if(a.startsWith('resource-'))return openResource(a.slice(9));
    if(a==='ledger-sync')return openModal('Ledger Sync · coming soon',`<p>Ledger wallet sync is planned for a future update. This is a preview of where you’ll connect your Ledger accounts.</p>`,`<a class="btn secondary full" href="https://www.ledger.com/" target="_blank" rel="noopener noreferrer">Explore Ledger${icon('upRight')}</a><button class="demo-link full" data-action="close-modal">Back to WHOO</button>`);
    if(a==='ledger-banner-slide'){const rail=$('#ledger-banner-rail');if(rail)rail.scrollTo({left:Math.max(0,Math.min(2,Number(el.dataset.index)||0))*rail.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
    if(a==='wallet-transfer')return showWalletTransfer();
    if(a==='wallet-swap')return showWalletAction('swap');
    if(a==='wallet-buy')return showWalletAction('buy');
    if(a==='add-wallet')return showAddWallet();
    if(a==='topup-card')return openCardTopup(el.dataset.id);
    if(a==='confirm-card-topup')return confirmCardTopup();
    if(a==='edit-card-topup')return openCardTopup(el.dataset.id,el.dataset.wallet);
    if(a==='max-load'){const c=getCard(el.dataset.id),w=getWallet($('#source-wallet')?.value);if(!c||!w)return;const input=$('#amount');if(input){input.value=(maxLoad(c,w)/100).toFixed(2);updateFees();}return;}
    if(a==='add-to-wallet')return openModal('Add to '+el.dataset.provider,`<p>This previews the wallet handoff for your eligible WHOO card. Live availability depends on your card issuer and region.</p>`,`<button class="btn primary full" data-action="close-modal">Got it</button>`);
    if(a==='backdrop'){if(event.target===el)closeModal();return;}
    if(a==='close-modal')return closeModal();
    if(a==='chat')return showChat();
    if(a==='chat-topic')return sendChat(el.dataset.topic);
    if(a==='copy')return copy(el.dataset.value);
    if(a==='transaction')return showTransaction(el.dataset.id);
    if(a==='hide-balance'){hideBalance=!hideBalance;return render();}
    if(a==='reveal'){reveal=!reveal;return render();}
    if(a==='freeze'){const c=getCard(el.dataset.id);if(!c||c.status==='selected')return;c.status=c.status==='active'?'frozen':'active';persist();render();return toast(c.status==='frozen'?'Card frozen. You’re in control.':'Card unfrozen. Ready when you are.');}
    if(a==='preset'){const input=$('#amount');if(input){input.value=el.dataset.value;input.dispatchEvent(new Event('input',{bubbles:true}));}return;}
    if(a==='filter-history'){historyFilter=el.dataset.filter;historySearch=$('#history-search')?.value||'';const r=parseRoute();if(r.id)location.hash='/activity';else render();return;}
    if(a==='auth-method'){authMethod=el.dataset.method;render();return;}
    if(a==='social')return openModal('Continue with '+el.dataset.provider,`<p>This is the quick sign-in screen for the design preview. Live ${esc(el.dataset.provider)} sign-in will be connected when the app is integrated.</p><div class="account-choice"><span class="avatar">AM</span><div><strong>Alex Morgan</strong><p>Sample account</p></div></div>`,`<button class="btn primary full" data-action="social-demo">Continue to demo${icon('arrow')}</button>`);
    if(a==='social-demo'){closeModal();afterLogin();return toast('Welcome to the WHOO demo');}
    if(a==='resend')return toast('Demo code: 1234 · no email or SMS is sent');
    if(a==='confirm-deposit'){const t=getTx(el.dataset.id);if(!t||t.type!=='deposit'||t.status!=='awaiting_payment'||!t.amountAtomic)return;let w=getWallet(t.walletId);if(!w){if(!networkOptions(t.asset).some(n=>n[0]===t.network))return;w=makeWallet(t.asset,t.network);state.wallets.push(w);}w.balanceAtomic=(BigInt(w.balanceAtomic)+BigInt(t.amountAtomic)).toString();t.status='confirmed';persist();render();return toast('Demo crypto deposit confirmed');}
    if(a==='submit-withdrawal'){if(!draftWithdrawal)return;const d=draftWithdrawal,w=getWallet(d.walletId);if(!w||BigInt(d.amountAtomic)>BigInt(w.balanceAtomic))return toast('This wallet balance has changed. Please review the amount.');draftWithdrawal=null;w.balanceAtomic=(BigInt(w.balanceAtomic)-BigInt(d.amountAtomic)).toString();const id=uid('wd');state.transactions.unshift({...d,id,type:'withdrawal',title:d.asset+' withdrawal',subtitle:d.network+' · To external wallet',amount:-d.amount,status:'pending',date:now()});persist();go('withdraw/success/'+id);return;}
    if(a==='export')return exportActivity();
    if(a==='share'){const link=location.href.split('#')[0]+'#/signup?ref=WHOOJ8';if(navigator.share)navigator.share({title:'A little more freedom with WHOO',text:'Join my little circle at WHOO. Invite code: WHOOJ8',url:link}).catch(e=>{if(e.name!=='AbortError')copy(link);});else copy(link);return;}
    if(a==='alerts')return openModal('Your updates.',state.transactions.length?state.transactions.slice(0,3).map(t=>`<div class="notification">${icon(t.type==='deposit'?'downLeft':'card')}<p><strong>${esc(t.title)}</strong>${esc(t.subtitle)} · ${esc(t.status)}</p></div>`).join(''):`<div class="center" style="padding:22px 0">${icon('bell')}<p style="margin-top:12px">No updates yet. Choose your card and top up your wallet to get started.</p></div>`);
    if(a==='notifications-toggle'){state.notifications=!state.notifications;persist();render();return toast('Notification preference saved for this preview');}
