    if(a==='signout')return openModal('See you in a little while.',`<p>Sign out of the demo and explore the welcome screen. Your sample data stays in this browser.</p>`,`<button class="btn primary full" data-action="do-signout">Sign out${icon('logout')}</button><button class="btn outline full" data-action="close-modal">Stay here</button>`);
    if(a==='do-signout'){reveal=false;go('login');return;}
    if(a==='reset')return openModal('A fresh little start?',`<p>Reset the sample balance, cards, messages and activity in this browser.</p>`,`<button class="btn primary full" data-action="do-reset">Reset demo</button><button class="btn outline full" data-action="close-modal">Keep exploring</button>`);
    if(a==='do-reset'){state=seed();draftWithdrawal=null;draftDeposit=null;draftFunding=null;recoveryView=null;homeSession=null;resourceVisits.clear();homeVisit=0;try{sessionStorage.removeItem(HOME_SESSION_KEY);localStorage.removeItem(HOME_ROTATION_KEY);}catch{}reveal=false;hideBalance=false;persist();go('onboarding/1');return toast('Demo reset. A fresh little start.');}
    if(a==='security-pin')return openModal('Your security PIN.',`<p>Choose a four-digit PIN to preview this screen. It is not used for account access.</p><form data-form="pin" style="margin-top:20px">${errorBox()}<label class="field"><span class="field-label">Four-digit PIN</span><input class="input" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="new-password" required></label><button class="btn primary full" type="submit">Preview PIN confirmation</button></form>`);
    if(a==='security-biometric')return openModal('A familiar little touch.',`<div class="success-orb">${icon('shield')}</div><p>Face ID and fingerprint sign-in will be considered when the web experience becomes an app. This screen previews where the option will live.</p>`);
