  document.addEventListener('input',event=>{
    if(event.target.id==='amount')updateFees();
    if(event.target.id==='history-search'){historySearch=event.target.value;$('#history-results').innerHTML=historyResults();}
    if(event.target.classList.contains('otp-digit')){event.target.value=event.target.value.replace(/\D/g,'').slice(-1);if(event.target.value){const inputs=$$('.otp-digit');const i=inputs.indexOf(event.target);inputs[i+1]?.focus();}}
  });
  document.addEventListener('change',event=>{if(event.target.id==='recovery-understood'){const button=$('#recovery-reveal-button');if(button)button.disabled=!event.target.checked;}if(event.target.id==='recovery-written'){const button=$('#recovery-confirm-button');if(button)button.disabled=!event.target.checked;}if(event.target.id==='asset-select'){const select=$('#network-select');select.innerHTML=options(networkOptions(event.target.value),'');}if(event.target.id==='source-wallet'){const w=getWallet(event.target.value);if(!w)return;const depositBox=$('#native-deposit-amount'),withdrawBox=$('#native-withdraw-amount');if(depositBox)depositBox.innerHTML=nativeAmountField(w,'Amount to receive');if(withdrawBox)withdrawBox.innerHTML=nativeAmountField(w,'Amount to withdraw');updateFees();}});
  document.addEventListener('paste',event=>{if(!event.target.classList.contains('otp-digit'))return;const code=(event.clipboardData?.getData('text')||'').replace(/\D/g,'').slice(0,4);if(!code)return;event.preventDefault();const inputs=$$('.otp-digit');code.split('').forEach((d,i)=>inputs[i].value=d);inputs[Math.min(code.length,3)]?.focus();});
  document.addEventListener('keydown',event=>{
    if(event.key==='Escape')closeModal();
    if(event.key==='Backspace'&&event.target.classList.contains('otp-digit')&&!event.target.value){const inputs=$$('.otp-digit');inputs[inputs.indexOf(event.target)-1]?.focus();}
    const modal=$('.modal');if(event.key==='Tab'&&modal){const list=[...modal.querySelectorAll('a[href],button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled);const first=list[0],last=list[list.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  });
  document.addEventListener('submit',event=>{
    const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));const kind=form.dataset.form;
    if(kind==='auth'){const contact=String(data.contact).trim();if(authMethod==='phone'&&!/^\+?[\d\s()-]{6,20}$/.test(contact))return error('Enter a valid phone number.');authContact=authMethod==='phone'?data.dial+' '+contact:contact;go('verify');return;}
    if(kind==='verify'){if([0,1,2,3].map(i=>data['digit'+i]).join('')!=='1234')return error('Use the preview code 1234.');if(authContact){if(authMethod==='email')state.user.email=authContact;else state.user.phone=authContact;persist();}afterLogin();return toast('You’re in. Welcome to WHOO.');}
    if(kind==='profile'){if(!data.name.trim())return error('Please enter your name.');state.user={...state.user,name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim(),country:data.country};persist();go('profile');return toast('Your details are saved');}
    if(kind==='pin'){if(!/^\d{4}$/.test(data.pin))return error('Use four digits.');closeModal();return toast('PIN confirmation preview complete. No PIN is stored.');}
    if(kind==='chat')return sendChat(String(data.message));
    if(kind==='recovery-reveal')return revealRecoveryPhrase(data.understood==='on');
    if(kind==='recovery-confirm')return finishRecoveryBackup(data.written==='on');
    if(kind==='add-wallet'){
      if(!assetById(data.asset)||!networkOptions(data.asset).some(n=>n[0]===data.network))return error('Choose a supported asset and network.');
      const id=walletId(data.asset,data.network);if(getWallet(id))return error('You already have this wallet. Choose a different asset or network.');
      state.wallets.push(makeWallet(data.asset,data.network));persist();go('wallet/'+id);return toast(data.asset+' wallet added.');
    }
    if(kind==='deposit-amount'){
      const w=getWallet(data.walletId);if(!w)return error('Choose one of your wallets.');
      const amount=parseAtomic(data.amount,w.asset);if(amount===null||amount<=0n||valueCents(amount,w.asset)>100000000)return error('Enter a positive '+w.asset+' amount with no more than '+assetById(w.asset).decimals+' decimal places, up to $1,000,000 equivalent.');
      draftDeposit={walletId:w.id,amountAtomic:amount.toString()};const id=uid('dep');
      state.transactions.unshift({id,type:'deposit',title:w.asset+' deposit',subtitle:w.network+' · To '+assetById(w.asset).name+' wallet',asset:w.asset,network:w.network,walletId:w.id,amountAtomic:amount.toString(),amount:valueCents(amount,w.asset),status:'awaiting_payment',date:now()});
      persist();go('deposit/payment/'+id);return;
    }
    if(kind==='withdraw'){
      const w=getWallet(data.walletId);if(!w)return error('Choose one of your wallets.');
      const amount=parseAtomic(data.amount,w.asset);if(amount===null||amount<=0n)return error('Enter a valid '+w.asset+' amount with up to '+assetById(w.asset).decimals+' decimal places.');
      if(valueCents(amount,w.asset)<1000)return error('The minimum demo withdrawal is $10.00 equivalent.');
      if(amount>BigInt(w.balanceAtomic))return error('This amount is more than the available balance in this '+w.asset+' wallet.');
      const address=String(data.address||'').trim();if(address.length<8||address.length>200)return error('Enter a receiving wallet address.');
      const fee=(amount*3n+50n)/100n;
      draftWithdrawal={walletId:w.id,amountAtomic:amount.toString(),feeAtomic:fee.toString(),netAtomic:(amount-fee).toString(),amount:valueCents(amount,w.asset),fee:valueCents(fee,w.asset),asset:w.asset,network:w.network,address};go('withdraw/review');return;
    }
    if(kind==='fund-card'){
      const c=getCard(form.dataset.id),w=getWallet(data.walletId);if(!c)return error('This card could not be found.');if(!w||BigInt(w.balanceAtomic)<=0n)return error('Choose a funded crypto wallet.');
      if(c.status==='frozen')return error('Unfreeze this card before topping up.');
      const amount=parseCardAmount(data.amount);if(amount===null||amount<=0)return error('Enter a valid USDT amount with up to two decimal places, up to 1,000,000.');
      const min=c.status==='selected'?1000:100;if(amount<min)return error('The minimum amount is '+(min/100).toFixed(2)+' USDT.');
      const q=feeQuote(c,amount),source=sourceAtomicFor(q.total,w);if(source>BigInt(w.balanceAtomic))return error('Not enough '+w.asset+' in this wallet, including fees. You need '+nativeMoney(source,w.asset)+'. Your available balance is '+nativeMoney(w.balanceAtomic,w.asset)+'.');
      reviewCardTopup(c,w,amount);return;
    }

  });
  window.addEventListener('pagehide',()=>{if(recoveryView){recoveryView=null;render();}});
